    }
    bool d1 = true, d2 = true;
    for (int i = 0; i < n; i++) {
      if (board[i][i] != ch) d1 = false;
      if (board[i][n - 1 - i] != ch) d2 = false;
    }
    return d1 || d2;
  }

public:
