};

func tictactoe(board []string) string {
	n := len(board)
	win := func(ch byte) bool {
		for i := 0; i < n; i++ {
			row, col := true, true
			for j := 0; j < n; j++ {
				if board[i][j] != ch {
					row = false
				}
				if board[j][i] != ch {
					col = false
				}
			}
			if row || col {
				return true
			}
		}
		d1, d2 := true, true
		for i := 0; i < n; i++ {
			if board[i][i] != ch {
				d1 = false
			}
			if board[i][n-1-i] != ch {
				d2 = false
			}
		}
		return d1 || d2
	}
	if win('X') {
		return "X"
	}
	if win('O') {
		return "O"
	}
	for _, row := range board {
		for i := 0; i < len(row); i++ {
			if row[i] == ' ' {
				return "Pending"
			}
		}
	}
	return "Draw"
}

class Solution {
  private boolean win(String[] board, char ch) {
    int n = board.length;
    for (int i = 0; i < n; i++) {
      boolean row = true, col = true;
      for (int j = 0; j < n; j++) {
        if (board[i].charAt(j) != ch) row = false;
        if (board[j].charAt(i) != ch) col = false;
      }
      if (row || col) return true;
    }
    boolean d1 = true, d2 = true;
    for (int i = 0; i < n; i++) {
      if (board[i].charAt(i) != ch) d1 = false;
      if (board[i].charAt(n - 1 - i) != ch) d2 = false;
    }
    return d1 || d2;
  }

  public String tictactoe(String[] board) {
    if (win(board, 'X')) return "X";
    if (win(board, 'O')) return "O";
    for (String row : board)
      for (int i = 0; i < row.length(); i++)
        if (row.charAt(i) == ' ') return "Pending";
    return "Draw";
  }
}

class Solution:
    def tictactoe(self, board: List[str]) -> str:
        n = len(board)

        def win(ch: str) -> bool:
            for i in range(n):
                if all(board[i][j] == ch for j in range(n)):
                    return True
                if all(board[j][i] == ch for j in range(n)):
                    return True
            if all(board[i][i] == ch for i in range(n)):
                return True
            if all(board[i][n - 1 - i] == ch for i in range(n)):
                return True
            return False

        if win("X"):
            return "X"
        if win("O"):
            return "O"
        for row in board:
            if " " in row:
                return "Pending"
        return "Draw"

impl Solution {
  pub fn tictactoe(board: Vec<String>) -> String {
    let grid: Vec<Vec<char>> = board.iter().map(|s| s.chars().collect()).collect();
    let n = grid.len();
    let win = |ch: char| -> bool {
      for i in 0..n {
        if (0..n).all(|j| grid[i][j] == ch) || (0..n).all(|j| grid[j][i] == ch) {
          return true;
        }
      }
      if (0..n).all(|i| grid[i][i] == ch) || (0..n).all(|i| grid[i][n - 1 - i] == ch) {
        return true;
      }
      false
    };
    if win('X') {
      return "X".to_string();
    }
    if win('O') {
      return "O".to_string();
    }
    for row in &grid {
      for &c in row {
        if c == ' ' {
          return "Pending".to_string();
        }
      }
    }
    "Draw".to_string()
  }
}

const tictactoe = (board: string[]): string => {
  const n = board.length;
  const win = (ch: string): boolean => {
    for (let i = 0; i < n; i++) {
      let row = true;
      let col = true;
      for (let j = 0; j < n; j++) {
        if (board[i][j] !== ch) row = false;
        if (board[j][i] !== ch) col = false;
      }
      if (row || col) return true;
    }
    let d1 = true;
    let d2 = true;
    for (let i = 0; i < n; i++) {
      if (board[i][i] !== ch) d1 = false;
      if (board[i][n - 1 - i] !== ch) d2 = false;
    }
    return d1 || d2;
  };
  if (win('X')) return 'X';
  if (win('O')) return 'O';
  for (const row of board) if (row.includes(' ')) return 'Pending';
  return 'Draw';
};
